    # Handle the issue with windows not parsing shebangs
    if sys.platform == "win32":
        # Detect if the first argument is a shebang
        if fixed_cmd[0].startswith("#!"):
            # Strip the shebang from the first argument
            fixed_cmd[0] = fixed_cmd[0][2:]

    # Handle the issue with deep-path shebangs
    if not fixed_cmd[0].startswith("/"):
        # Retrieve the current working directory
        cwd = os.getcwd()

        # Resolve the relative path to an absolute path
        fixed_cmd[0] = os.path.join(cwd, fixed_cmd[0])

    return tuple(fixed_cmd)

