def extostr(e, max_level=30, max_path_level=5):
    try:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        lines = traceback.format_exception(exc_type, exc_value, exc_traceback)
        if max_level != None and max_level > 0:
            lines = lines[:max_level]
        if max_path_level != None and max_path_level > 0:
            for i in range(max_path_level - 1):
                lines = [l.replace("File \"", "").replace("", "") for l in lines]
        msg = "".join(lines)
        return msg[7:-1]
    except:
        try:
            msg = "Failed to format exception."
        except:
            msg = "Unknown exception"
    return msg

