        # Add the attribute name and description to the dictionary
        names_and_descriptions[name] = getter_method.description

    # If 'all' parameter is True, include protected and private attributes
    if all:
        # Iterate over the attributes defined in the interface class
        for name in dir(cls):
            # Check if the attribute is not defined in the first iteration
            if name not in names_and_descriptions:
                # Check if the attribute is a property with a getter method defined
                try:
