def integral(bins, edges):
    try:
        if len(bins) != len(edges) - 1:
            raise ValueError("Length of bins and edges for integral calculation should be equal")
        sum = 0
        for i in range(len(bins)):
            sum += (bins[i] + bins[i+1]) * (edges[i+1] - edges[i]) / 2
        return sum
    except ValueError as ve:
        raise ValueError(f"Invalid inputs for integral calculation: {ve}")
    except TypeError as te:
        raise TypeError(f"Invalid type for integral calculation: {te}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error during integral calculation: {e}")

