def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.
    """
    # Check if the input is a dict and not None
    if manifest_dict is None or not isinstance(manifest_dict, dict):
        raise ValueError("Invalid input: 'manifest_dict' must be a dict")

    # Create a new dict with the same keys as the input
    new_dict = {key: None for key in manifest_dict.keys()}

    # If 'first_level' is True, copy the values of the identifying fields from the manifest file
    if first_level:
        # Check if the keys are present in the manifest dict
        if "namespace" in manifest_dict:
            new_dict["namespace"] = manifest_dict["namespace"]
        if "kind" in manifest_dict:
            new_dict["kind"] = manifest_dict["kind"]
        if "metadata" in manifest_dict:
            if "name" in manifest_dict["metadata"]:
                new_dict["metadata"]["name"] = manifest_dict["metadata"]["name"]
        if "spec" in manifest_dict:
            new_dict["spec"] = manifest_dict["spec"]

    return new_dict

