def generate_default_observer_schema_dict(manifest_dict: Dict[str, Any], first_level: bool = False) -> Dict[str, Any]:
    """Generate a partial observer schema from a Kubernetes manifest dictionary."""
    if not isinstance(manifest_dict, dict):
        return {}

    # Create a new dictionary with the same keys as the manifest dictionary
    observer_schema = {key: None for key in manifest_dict.keys()}

    # Set the identifying fields to the values from the manifest file for the first_level schema
    if first_level:
        for field in ["name", "group", "version"]:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]
    else:
        for field in ["name"]:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]

    # Recursively generate the observer schema for each value in the manifest dictionary
    for field, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[field] = generate_default_observer_schema_dict(value, first_level=first_level)
        elif isinstance(value, list):
            observer_schema[field] = [generate_default_observer_schema_dict(item, first_level=first_level) for item in value]

    return observer_schema

