def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    # Check if the response is not None and the observer_schema is not empty
    if response is None or observer_schema is None:
        raise ValueError("Response and observer schema cannot be None")

    # Iterate over the response and initialize the values in the last_applied_manifest
    for item in response:
        # Initialize the item object if it is not yet present in the last_applied_manifest
        if item not in last_applied_manifest:
            last_applied_manifest.append(item)

        # If the item is a list, recursively call the update_last_applied_manifest_list_from_resp function
        if isinstance(item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[item], observer_schema[item], item)

        # If the item is a dict, recursively call the update_last_applied_manifest_dict_from_resp function
        elif isinstance(item, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[item], observer_schema[item], item)

        # If the item is a str, int, or bool, set it to the last_applied_manifest
        else:
            last_applied_manifest[item] = item

        # If the item is not found in the response, remove it from the last_applied_manifest
        if item not in response:
            last_applied_manifest.remove(item)

    return last_applied_manifest

