def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, values in observer_schema.items():
        if field not in last_applied_manifest:
            last_applied_manifest[field] = []
        if len(values) > 0 and values[0].get("observed_fields") is not None:
            if field not in response or len(response[field]) == 0:
                raise KeyError(f"Observed field {field} is not present in Kubernetes response")
            for subfield, subvalues in values[0]["observed_fields"].items():
                if subfield not in last_applied_manifest[field]:
                    last_applied_manifest[field][subfield] = []
                for subsubfield in subvalues:
                    if subsubfield not in response[field][0]:
                        raise KeyError(f"Observed subfield {subsubfield} is not present in Kubernetes response")
                    last_applied_manifest[field][subfield].append(response[field][0][subsubfield])
        else:
            if field not in response:
                raise KeyError(f"Observed field {field} is not present in Kubernetes response")
            last_applied_manifest[field].append(response[field])
    return last_applied_manifest

def generate_default_observer_schema(app):
    from krake.data.kubernetes import Application
    from krake.data.schema import ObserverSchema

    if not isinstance(app, Application):
        raise TypeError("`app` must be an instance of Application")

    observer_schema = ObserverSchema()

    for resource in app.spec.manifest:
        if "observer-schema" not in resource.metadata:
            resource_observer_schema = ObserverSchema()
            observer_schema.merged_with(resource_observer_schema)

    return observer_schema

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_observer_schema = {}
    for resource in app.spec.manifest:
        if 'observer_schema' not in resource:
            default_observer_schema[resource.kind] = {
                'version': '1.0',
                'properties': {
                    'status': {
                        'properties': {
                            'ready': {'type': 'boolean'},
                            'observed_generation': {'type': 'integer'},
                            'updated': {'type': 'string'},
                        }
                    }
                }
            }
    return default_observer_schema

import copy

def generate_default_observer_schema(app):
    # Copy the default observer schema
    schema = copy.deepcopy(app.spec.manifest.observer_schema)

    # Iterate over all resources present in the manifest
    for resource in app.spec.manifest:
        # Skip resources where a custom observer schema has been specified
        if resource.observer_schema is not None:
            continue

        # Populate the default observer schema for this resource
        for property_name in resource.properties:
            if property_name not in schema:
                schema[property_name] = {}
            for sub_property_name in resource.properties[property_name]:
                if sub_property_name not in schema[property_name]:
                    schema[property_name][sub_property_name] = {}
                for operation in resource.properties[property_name][sub_property_name]:
                    if operation not in schema[property_name][sub_property_name]:
                        schema[property_name][sub_property_name][operation] = {}

    return schema

def generate_default_observer_schema(app):
    observer_schema = {}
    for resource in app.spec.manifest.values():
        if 'observerSchema' not in resource:
            observer_schema[resource.name] = {}
            for field in resource.fields:
                if 'observerSchema' not in field.tags:
                    observer_schema[resource.name][field.name] = {}
            if 'observerSchema' not in resource.tags:
                resource.tags['observerSchema'] = observer_schema[resource.name]
    return observer_schema

def format(sql, params):
    if not isinstance(params, (dict, list)):
        raise ValueError("params must be a dict or list")

    if isinstance(params, list):
        if len(params) != len(set(params)):
            raise ValueError("params must not contain duplicate values")

        params = dict((i, v) for i, v in enumerate(params))

    if SQLParams.in_style == "named":
        if not isinstance(params, dict):
            raise ValueError("params must be a dict")

        sql = sql.replace("%s", ":{}")
        params = dict((k, v) for k, v in params.items())
    else:
        if not isinstance(params, list):
            raise ValueError("params must be a list")

        sql = sql.replace("%s", "?")

    return (sql, params)

def format(sql, params):
    formatted_sql = ""
    out_params = None

    if isinstance(params, dict):
        formatted_sql = sql.replace(":", "@")
        out_params = {key: value for key, value in params.items()}
    elif isinstance(params, (list, tuple)):
        formatted_sql = sql.replace("?", "@")
        out_params = list(params)
    else:
        raise ValueError("Invalid parameter type")

    return (formatted_sql, out_params)

def convert_to_out_style_parameters(sql, params):
    """
    Convert the SQL query to use out-style parameters instead of in-style parameters.

    :type sql: str or bytes
    :type params: dict or list
    :rtype: tuple
    """
    # Validate input
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes")
    if not isinstance(params, (dict, list)):
        raise TypeError("params must be a dictionary or list")

    # Convert in-style parameters to out-style parameters
    out_style_params = {}
    in_style_params = []
    for param, value in params.items():
        if isinstance(param, str):
            out_style_params[param] = value
        else:
            in_style_params.append(value)

    # Replace in-style parameters with out-style parameters in the SQL query
    if isinstance(sql, str):
        return sql.replace("?", "@?"), out_style_params
    else:
        # Convert bytes to str for the sake of replace and return
        return sql.decode().replace(b"?", b"@?").encode(), out_style_params

def format(sql, params):
    # Check if the input values are valid
    if not isinstance(sql, (str, bytes)):
        raise ValueError("Invalid type for 'sql'. Expected str or bytes.")
    if not isinstance(params, (dict, list)):
        raise ValueError("Invalid type for 'params'. Expected dict or list.")

    # Check if the input values are empty
    if sql == "":
        raise ValueError("Empty 'sql' string.")
    if params == []:
        raise ValueError("Empty 'params' list.")

    # Check if the SQL query is malformed
    if not isinstance(sql, str):
        sql = str(sql, 'utf-8')
    if "?" not in sql:
        raise ValueError("Invalid SQL query. '?' placeholder not found.")

    # Check if the parameter style is valid
    if not isinstance(params, dict) and not isinstance(params, list):
        raise ValueError("Invalid type for 'params'. Expected dict or list.")
    if isinstance(params, dict) and "?" not in params.keys():
        raise ValueError("Invalid dictionary for 'params'. '?' key not found.")
    if isinstance(params, list) and len(params) == 0:
        raise ValueError("Invalid list for 'params'. List is empty.")

    # Check if the number of parameters in the query matches the number of parameters passed
    param_count = len(sql.split("?")) - 1
    if isinstance(params, dict):
        if len(params) != param_count:
            raise ValueError("Number of parameters in 'params' mismatch. "
                             "Expected {} parameters found: {}.\n".format(param_count, len(params)))
    elif isinstance(params, list):
        if len(params) != param_count:
            raise ValueError("Number of parameters in 'params' mismatch. "
                             "Expected {} parameters found: {}.\n".format(param_count, len(params)))

    # Format the SQL query using the out-style parameters
    formatted_sql, formatted_params = sql.replace("?", ":%s"), []

def formatmany(sql, many_params):
    # Check if the input is valid
    if not isinstance(sql, str):
        raise ValueError("SQL query must be a string")
    if not isinstance(many_params, Iterable):
        raise ValueError("Many parameters must be an iterable")

    # Initialize the formatted SQL query and a list to store the converted parameters
    formatted_sql = ""
    params = []

    # Iterate over each set of in-style parameters
    for i, params_list in enumerate(many_params):
        # Check if the current set of parameters is valid
        if not isinstance(params_list, (Mapping, Sequence)):
            raise ValueError(f"Parameters for input {i} must be a mapping or a sequence")

        # Check if the mapping is using ordinal parameters
        if isinstance(params_list, Mapping):
            if not all([isinstance(k, (str, int)) and isinstance(v, Any) for k, v in params_list.items()]):
                raise ValueError("Invalid parameter mapping. Each item must be a (str, int) pair")

        # Check if the sequence is using ordinal parameters
        elif isinstance(params_list, Sequence) and not all([isinstance(p, Any) for p in params_list]):
            raise ValueError("Invalid parameter sequence. Each item must be an object")

        # Format the SQL query using out-style parameters
        formatted_sql = sql.format(*params_list)
        if i < len(many_params) - 1:
            formatted_sql += ","

        # Add the converted parameters to the list
        if isinstance(params_list, Sequence):
            params.append(list(params_list))
        else:
            params.append({k: v for k, v in params_list.items()})

    return formatted_sql, params

def formatmany(sql, many_params):
    formatted_sql = ""
    param_list = []
    if isinstance(many_params, dict):
        for key, value in many_params.items():
            param_list.append({key: value})
    elif isinstance(many_params, list):
        for item in many_params:
            param_list.append(item)
    for param in param_list:
        formatted_sql += repr(param) + ","
    return formatted_sql[:-1], param_list

def formatmany(sql, many_params):
    formatted_sql = sql
    formatted_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            formatted_params.append({k: v for k, v in params.items()})
        else:
            formatted_params.append(list(params))
    return formatted_sql, formatted_params

