def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    output = ''
    if prefix:
        output += prefix
    for field in self:
        if field.has_errors:
            output += f'{field.label} is invalid with errors:\n'
            for error in field.errors:
                output += f'- {error}\n'
    return output

