def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    try:
        content_index = inventory.content_index
    except AttributeError:
        raise ValueError("Provided inventory does not contain a content_index")

    try:
        version_index = inventory.version_index
    except AttributeError:
        raise ValueError("Provided inventory does not contain a version_index")

    if version not in version_index:
        raise ValueError("Provided version is not present in the inventory")

    logical_path_map = {}

    for state, component_ids in content_index.items():
        content_files = set()

        for component_id in component_ids:
            if not component_id or component_id not in inventory:
                continue

            component = inventory[component_id]
            version_entry = component["version_entries"][version]

            if "files" in version_entry:
                content_files.update(version_entry["files"])

        logical_path_map[state] = content_files

    return logical_path_map

