    """
    Extracts the number and supplement from the given issue element.

    :param issue: The issue element to extract the number and supplement from.
    :return: A tuple of two elements, where the first element is the number and the second element is the supplement.
    """

    try:
        issue = issue.strip()
        if not issue or not issue.isalnum():
            raise ValueError("Invalid issue input: \"{}\"".format(issue))

        number = issue[:2]
        supplement = issue[2:]

        if number.isdigit() and supplement.isdigit():
            number = int(number)
            supplement = int(supplement)
        elif number.isdigit():
            number = int(number)
            supplement = None
        else:
