def absorb(args):
    """
    Given an args sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:

        A & (A | B) = A, A | (A & B) = A

    Negative absorption:

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    output = []
    for i in range(0, len(args), 2):
        if args[i] == "&" and args[i+1] == "|":
            output.append(args[i])
        elif args[i] == "|" and args[i+1] == "&":
            output.append(args[i])
        elif args[i] == "&" and args[i+1] == "~":
            output.append(args[i+1])
        elif args[i] == "|" and args[i+1] == "~":
            output.append(args[i+1])
        else:
            output.append(args[i])
    return output

def absorb(self, args):
    result = []
    for arg in args:
        if "~" in arg:
            # Negative absorption
            result.append(self.absorb(arg))
        else:
            # Absorption
            result.append("A")
    return result

