def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A command or list of commands to execute. If a list, will execute each command in sequence.
    :param args: A list of arguments to pass to the command.
    :param cwd: (optional) The working directory to run the command in.
    :param verbose: (optional) Print the command and its output to the console.
    :param hide_stderr: (optional) Hide the standard error stream.
    :param env: (optional) A dictionary of environment variables to use when running the command.
    :return: The exit code of the command.
    """

    if not isinstance(commands, list):
        commands = [commands]

    exit_code = 0
    for command in commands:
        try:
            if verbose:
                log(f'Executing command: {command}')

            if not isinstance(args, list):
                args = [args]

            proc = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True)
            output, error = proc.communicate()

            if not hide_stderr:
                log_stderr(error)

            if output:
                log(output)

            exit_code = proc.returncode
        except subprocess.CalledProcessError as error:
            log(f'Command failed with exit code {error.returncode}.')
            exit_code = error.returncode

    return exit_code


