def register_vcs_handler(vcs, method):
    # Check if the input is valid
    if not isinstance(vcs, str):
        raise TypeError("Expected a string for the VCS argument, but got " + str(type(vcs)))
    if not callable(method):
        raise TypeError("Expected a callable for the method argument, but got " + str(type(method)))

    # Try to register the handler
    try:
        vcs_handler = vcs_handlers[vcs]
    except KeyError:
        vcs_handlers[vcs] = dict()
        vcs_handler = vcs_handlers[vcs]

    # Check if the handler is already registered
    if method in vcs_handler:
        raise ValueError("The given method is already registered as the handler of " + vcs)

    # Register the method as the handler
    vcs_handler[method] = True
    return method


