public String findPathType(String path) {
    String type = null;
    File dir = new File(path);
    String[] files = dir.list();
    if (files != null) {
        for (String file : files) {
            if (file.startsWith("0=")) {
                type = "root";
                break;
            }
            if (file.endsWith(".ocfl.xml")) {
                type = "object";
                break;
            }
        }
        if (type == null) {
            type = "file";
        }
    } else {
        type = "error: could not list files";
    }
    return type;
}

def find_path_type(path):
    # check for OCFL Storage Root
    if "StorageRoot" in path:
        return "root"

    # check for OCFL Objects
    if path.startswith("Objects"):
        return "object"

    # check for Files
    if path.startswith("Files") and path.endswith(".ocfl"):
        return "file"

    # throw error otherwise
    raise ValueError("Could not determine directory type")

def find_path_type(path):
    try:
        with open(os.path.join(path, "0=*.txt")) as f:
            return "root" if "Storage Root" in f.read() else "object" if "Object" in f.read() else "file"

    except FileNotFoundError:
        return "unknown"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not params.get("extra_parameters"):
        params["extra_parameters"] = {}

    if not params["extra_parameters"].get("bug_ids"):
        params["extra_parameters"]["bug_ids"] = []

    if bug_ids:
        params["extra_parameters"]["bug_ids"] = bug_ids

    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(bug_ids, list):
        raise ValueError("Bug IDs must be a list")

    for param, bug_id in params.items():
        if bug_id in bug_ids:
            params[param] = bug_id

    return params

def amend_bzparams(self, params, bug_ids):
    # type: (Dict, List[str]) -> None
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("Params must be a dictionary")
    if not isinstance(bug_ids, list):
        raise TypeError("Bug IDs must be a list")
    for key, value in params.items():
        if key == "ID":
            if value not in bug_ids:
                params[key] = bug_ids[0]
        elif key == "CP":
            params[key] = ";".join(bug_ids)
        elif key == "BUGS":
            params[key] = ",".join(bug_ids)
        else:
            params[key] = value
        if params[key] is None:
            params[key] = ""
    return

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    try:
        # Check if the bug_ids are valid
        if not bug_ids:
            raise ValueError('No bug IDs provided')

        # Iterate over the bug IDs and add them to the params
        for bug_id in bug_ids:
            if not bug_id.isdigit():
                raise ValueError(f'Invalid bug ID: {bug_id}')
            params['bugs'] += f'-bugid{bug_id}'

    except (TypeError, ValueError) as e:
        raise RuntimeError(f'Failed to amend Bugzilla params: {e}')

    return params

