def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    if not unparsed_arguments:
        raise ValueError('At least one argument is required.')

    args = {}
    for argument in unparsed_arguments:
        if argument.startswith('-'):
            # Parse arguments as if they were for the "global" subparser
            args['global'] = argparse.Namespace(**vars(global_parser.parse_args(argument)))
        else:
            # Parse arguments as if they were for a subparser
            subparser_name, subparser_arguments = argument.split(' ', 1)
            subparser_namespace = argparse.Namespace(**vars(subparser_parsers[subparser_name].parse_args(subparser_arguments)))
            args[subparser_name] = subparser_namespace

    return args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_arguments = {}
    unclaimed_arguments = []
    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                subparser_arguments, remaining_arguments = subparser.parse_known_args([argument])
            except ArgumentError:
                # This subparser cannot handle this argument, try the next one.
                continue
            else:
                parsed_arguments[subparser_name] = subparser_arguments
                unclaimed_arguments.extend(remaining_arguments)
                break
        else:
            # No subparser was able to parse this argument, add it to the list of unclaimed arguments.
            unclaimed_arguments.append(argument)
    return parsed_arguments, unclaimed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for subparser in subparsers:
            try:
                subparser_args = subparser.parse_args(arg)
                parsed_args[subparser_args.name] = subparser_args
                break
            except:
                remaining_args.append(arg)

    return parsed_args, remaining_args

