def deep_merge(first, second):
    if not isinstance(first, ruamel.yaml.nodes.MappingNode) or not isinstance(
        second, ruamel.yaml.nodes.MappingNode
    ):
        return None
    result = {}
    for key, value in first.value.items():
        if key in second.value:
            result[key] = deep_merge(value, second.value[key])
        else:
            result[key] = value
    for key, value in second.value.items():
        if key not in result:
            result[key] = value
    return ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=list(result.items()))

def deep_merge_nodes(nodes):
    keys = {}
    for key, value in nodes:
