    return keys


def merge_nodes(node1, node2):
    if node1.id != node2.id:
        raise ValueError("Cannot merge nodes with different types")
    if isinstance(node1, ruamel.yaml.nodes.MappingNode):
        return ruamel.yaml.nodes.MappingNode(
            node1.tag,
            {
                key: merge_nodes(node1.value[key], node2.value.get(key, node2.value[key]))
                for key in node1.value.keys() | node2.value.keys()
            },
        )
    elif isinstance(node1, ruamel.yaml.nodes.SequenceNode):
        return ruamel.yaml.nodes.SequenceNode(
            node1.tag, [merge_nodes(item1, item2) for item1, item2 in zip(node1.value, node2.value)]
        )
    else:
        return node1


