    subparsers = parser.add_subparsers()

    for unparsed_argument in unparsed_arguments:
        try:
            argument = argparse.Namespace(unparsed_argument)
            subparser = subparsers.get(argument.subparser)
            if subparser is None:
                subparser = subparsers.add_parser(argument.subparser)
            namespace_map[argument.subparser] = subparser.parse_args(
                [argument.unparsed_arguments], namespace_map[argument.subparser])
