        for subparser in subparsers.values():
            if argument in subparser.prefix_chars and len(argument) > 1:
                # This argument is for a subparser, and it's a prefix
                subparser_name = argument[1:]
                if subparser_name in subparsers.keys():
                    # We have a matching subparser, and it's a prefix
                    args = subparser.parse_args(unparsed_arguments)
                    result_dict[subparser_name] = args
                    remaining_args = [arg for arg in unparsed_arguments if arg not in args]
                    break
            elif argument in subparser.choices:
                # This argument is for a subparser, and it's an explicit choice
                subparser_name = argument
                if subparser_name in subparsers.keys():
                    # We have a matching subparser, and it's an explicit choice
                    args = subparser.parse_args(unparsed_arguments)
                    result_dict[subparser_name] = args
                    remaining_args = [arg for arg in unparsed_arguments if arg not in args]
                    break

    # Check for any subparsers that weren't called and complain
    for subparser in subparsers.values():
        if subparser.action == "store":
            # No arguments were provided to this subparser
            current_subparser_name = subparser.prog.replace(".py", "")
            result_dict[current_subparser_name] = None
