def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

    try:
        unit_map = {"weeks": datetime.timedelta.weeks, "days": datetime.timedelta.days, "hours": datetime.timedelta.hours, "minutes": datetime.timedelta.minutes, "seconds": datetime.timedelta.seconds}
        return datetime.timedelta(**{unit_map[unit]: number})
    except KeyError:
        raise ValueError(f"Invalid time unit: {unit}")

    except (AttributeError, TypeError):
        raise ValueError(f"Invalid frequency: {frequency}")

    return parsed_frequency

