    """insert a value of a nested key into a dictionary"""
    # check if the key is valid
    if not isinstance(key, str):
        raise TypeError("key must be a string")

    # check if the value is valid
    if not isinstance(val, (int, float, str)):
        raise TypeError("value must be an integer, float, or a string")

    # check if the keys are valid
    for k in keys:
        if not isinstance(k, str):
            raise TypeError("keys must all be strings")

    # iterate through the keys and create the nested dictionary
    d = dic
    for k in keys:
        if k not in d:
            d[k] = {}
        d = d[k]

    # insert the value into the nested dictionary
    d[key] = val
    return dic

