def merge_extra_vars(vars_dict, extra_vars=None):
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if extra_vars is not None and not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list of dictionaries")

    if extra_vars is None or len(extra_vars) == 0:
        return vars_dict

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("extra_vars must be a list of dictionaries")

        for key, value in extra_var.items():
            if key not in vars_dict:
                vars_dict[key] = value
            elif isinstance(value, dict) and isinstance(vars_dict[key], dict):
                vars_dict[key] = merge_extra_vars(vars_dict[key], [value])
            else:
                vars_dict[key] = value

    return vars_dict

