    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        # Read the plugin spec
        with open(os.path.join(plugin_dir, "plugin.json")) as f:
            plugin_spec = json.load(f)

        # Flatten the dict
        flat_spec = {}
        for key, value in plugin_spec.items():
            if isinstance(value, dict):
                for subkey, subvalue in value.items():
                    flat_spec[f"{key}.{subkey}"] = subvalue
            else:
                flat_spec[key] = value

        return flat_spec
    except FileNotFoundError:
        # No plugin.json file found
        raise FileNotFoundError(f"No plugin.json file found in {plugin_dir}")
    except (JSONDecodeError, ValueError):
        # Incorrect JSON format or malformed plugin spec
        raise ValueError(f"Incorrect JSON format or malformed plugin spec in {plugin_dir}/plugin.json")

