def cli_spec(args):
    try:
        spec_results = run_specs(args)
        if args.docker and not spec_results['success']:
            # If the tests failed in a docker container, it's likely that the container ran out of memory.
            # In this case, we can try to increase the memory limit on the container to see if the tests pass.
            set_docker_memory_limit(args.docker_compose)
            spec_results = run_specs(args)
    except Exception as e:
        print(f'Error running specs: {e}')
        return 1
    else:
        if not spec_results['success']:
            print('There were test failures.')
            return 1
        else:
            print('Tests passed!')
